function getOwner(p){return state.people.find(x=>x.id===p.owner_id)}
function own(p){return !!state.me&&p?.owner_id===state.me.id}
function mine(){return state.places.filter(p=>p.owner_id===state.me?.id)}
function placeVisits(id){return state.visits.filter(v=>v.place_id===id).sort((a,b)=>new Date(b.visited_at)-new Date(a.visited_at))}
