 if(which==='forgot')return showModal(spotUi('استعادة كلمة المرور','Password reset'),`<form id="spotResetRequestForm"><p class="muted-small">${spotUi('اكتب اسم المستخدم. سيظهر طلبك للمالك، ولن يتم تغيير كلمة المرور حتى يتحقق من هويتك ويوافق على الطلب ويعطيك رمزًا مؤقتًا.','Enter your username. The owner must verify your identity and approve the reset, then securely give you a one-time code.')}</p>${field('spotResetUsername',spotUi('اسم المستخدم','Username'),'text','','required autocomplete="username" autocapitalize="none" spellcheck="false"')}<div class="modal-actions"><button class="btn primary wide" type="submit">${spotUi('إرسال طلب الاستعادة','Request password reset')}</button></div><div class="modal-actions">${btn(spotUi('لدي رقم طلب ورمز','I have a reset code'),'redeem-password','outline sm')}</div></form>`);
