async function loadSocial(){
  try{
    const {data:posts,error}=await sup.from('social_posts').select('*').order('created_at',{ascending:false}).limit(500);
    if(error)throw error;state.posts=posts||[];
    if(state.me){
      const [{data:edges,error:fe},{data:alerts,error:ne},{data:activity,error:ae}]=await Promise.all([
        sup.from('social_follows').select('follower_id,followed_id,notify_new_posts,created_at').limit(3000),
        sup.from('social_notifications').select('*').eq('recipient_id',state.me.id).order('created_at',{ascending:false}).limit(80),
        sup.from('spot_activity_notifications').select('*').eq('recipient_id',state.me.id).order('created_at',{ascending:false}).limit(100)
      ]);
      if(fe)throw fe;if(ne)throw ne;if(ae)throw ae;state.follows=edges||[];state.alerts=alerts||[];state.activity=activity||[];
    }else{state.follows=[];state.alerts=[];state.activity=[]}
    await spotLoadLikeStats(state.posts.map(p=>p.id));
  }catch(e){console.warn('social sync',e);state.posts=[];state.follows=[];state.alerts=[];state.activity=[]}
}
