async function uploadPhoto(input,folder){const file=$(`#${input}`)?.files?.[0];if(!file)return null;if(!state.online)throw new Error('يحتاج رفع الصور إلى اتصال بالإنترنت');if(file.size>16*1024*1024)throw new Error('حجم الصورة كبير؛ اختر صورة لا تتجاوز 16MB');if(!file.type.startsWith('image/')&&!/\.(heic|heif)$/i.test(file.name))throw new Error('اختر صورة صالحة');let blob=file;if(input==='placePhoto'){if(!window.SPOT_PLACE_CROP)throw Error('تعذر تحميل محرر الصورة؛ أعد فتح التطبيق');blob=await window.SPOT_PLACE_CROP.blob(file)}else try{const bmp=await createImageBitmap(file);const size=Math.min(1,1600/Math.max(bmp.width,bmp.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bmp.width*size);canvas.height=Math.round(bmp.height*size);canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.82))||file;bmp.close?.()}catch(e){if(!file.type.startsWith('image/'))throw new Error('صيغة الصورة غير مدعومة في هذا المتصفح. استخدم JPG أو PNG.')}const ext=blob.type==='image/jpeg'?'jpg':(blob.type.split('/')[1]||'png');const path=`${state.me.id}/${folder}/${Date.now()}-${spotUUID()}.${ext}`;const bucket=state.me.is_private&&folder!=='avatars'?'spot-private':'blog-media';const {error}=await sup.storage.from(bucket).upload(path,blob,{contentType:blob.type||'image/jpeg'});if(error)throw error;return bucket==='spot-private'?'spot-media:'+path:sup.storage.from(bucket).getPublicUrl(path).data.publicUrl}
function setBusy(form,on){state.busy=on;if(form.id==='placeForm'){document.getElementById('spotPlaceCrop')?.toggleAttribute('inert',on);const photo=document.getElementById('placePhoto');if(photo)photo.disabled=on;}$$('button[type="submit"]',form).forEach(b=>{b.disabled=on;b.dataset.label||=(b.textContent||'');b.textContent=on?'جاري الحفظ…':b.dataset.label})}
async function safeSave(form,fn){if(state.busy)return;setBusy(form,true);try{if(!READY)throw new Error('الاتصال بقاعدة Supabase غير مهيأ');if(!navigator.onLine)throw new Error('أنت دون اتصال. المسودة محفوظة ويمكنك إكمالها عند عودة الإنترنت.');await fn()}catch(err){console.error(err);alertToast('تعذر الحفظ: '+(err.message||'خطأ غير متوقع'))}finally{setBusy(form,false)}}
