async function spotAccountAction(action,params={},authenticated=false){
 const headers={'Content-Type':'application/json',apikey:SKEY};
 if(authenticated){const {data:{session}}=await sup.auth.getSession();if(!session)throw Error('سجّل الدخول بحساب المالك أولًا');headers.authorization='Bearer '+session.access_token}
 const res=await fetch(`${SURL}/functions/v1/spot-accounts`,{method:'POST',headers,body:JSON.stringify({action,...params})});
 const data=await res.json().catch(()=>({}));
 if(!res.ok||data.ok===false){const codes={USERNAME_TAKEN:spotUi('اسم المستخدم مستخدم مسبقًا.','Username already taken.'),INVALID_INPUT:spotUi('البيانات غير صالحة.','Invalid input.'),RATE_LIMIT:spotUi('محاولات كثيرة. حاول لاحقًا.','Too many attempts. Try later.'),FORBIDDEN:spotUi('لا توجد صلاحية.','Not authorized.'),ACCOUNT_NOT_AVAILABLE:spotUi('الحساب غير متاح للاستعادة؛ تواصل مع المالك.','Account unavailable. Contact the owner.'),INVALID_OR_EXPIRED_CODE:spotUi('رمز غير صحيح أو منتهي الصلاحية.','Invalid or expired code.'),NOT_PENDING:spotUi('الطلب غير متاح.','Request is no longer pending.')};throw Error(codes[data.error]||spotUi('تعذر إكمال الطلب، حاول لاحقًا.','Could not complete request. Try again later.'))}
 return data;
}
