async function login(form){await safeSave(form,async()=>{const identifier=formValue('loginIdentifier').toLowerCase().replace(/^@/,''),password=formValue('loginPassword');if(!identifier||!password)throw new Error('أدخل بيانات الدخول');localStorage.setItem('thawaqV3Remember', $('#loginRemember').checked?'1':'0');const res=await fetch(`${SURL}/functions/v1/login-identifier`,{method:'POST',headers:{'Content-Type':'application/json','apikey':SKEY},body:JSON.stringify({action:'login',identifier,password})});const body=await res.json();if(!res.ok||!body?.session){const x={EMAIL_NOT_CONFIRMED:'حساب قديم بحاجة إلى تفعيل؛ تواصل مع المالك',ACCOUNT_DISABLED:'حسابك موقوف، تواصل مع المالك',INVALID_CREDENTIALS:'اسم المستخدم أو كلمة المرور غير صحيحة',RATE_LIMIT:'محاولات كثيرة، حاول لاحقًا'};throw new Error(x[body?.code]||'تعذر تسجيل الدخول')}const {data,error}=await sup.auth.setSession({access_token:body.session.access_token,refresh_token:body.session.refresh_token});if(error)throw error;state.session=data.session;await loadData({silent:true});closeModal();state.tab='home';render();alertToast('حيّاك في Spot ✨')})}
async function savePlace(form){await safeSave(form,async()=>{if(!requiredLogin())return;const id=form.dataset.id;const old=state.places.find(p=>p.id===id);if(old&&!own(old))throw new Error('لا توجد صلاحية تعديل');const name=formValue('placeName'),city=formValue('placeCity'),type=formValue('placeType'),notes=formValue('placeNotes'),mapsUrl=formValue('placeMapsUrl');if(!validGoogleMapLink(mapsUrl))throw new Error('ضع رابط Google Maps صحيحًا أو اترك الموقع فارغًا؛ لن نختار موقعًا تلقائيًا');if(!name||!city||!['restaurant','cafe','tea'].includes(type))throw new Error('اسم المكان والمدينة والتصنيف مطلوبة');const photo=await chosenPhoto('placePhoto','covers'),payload={name,city,type,notes,maps_url:mapsUrl||null,...photo?{cover_url:photo.url,cover_credit:photo.credit,cover_source:photo.source}:{}};let placeId=id;
 if(old){const {error}=await sup.from('places').update(payload).eq('id',id);if(error)throw error;}else{const {data,error}=await sup.from('places').insert({...payload,owner_id:state.me.id}).select('id').single();if(error)throw error;placeId=data.id;const {data:visit,error:ve}=await sup.from('visits').select('id').eq('place_id',placeId).order('created_at',{ascending:true}).limit(1).maybeSingle();if(ve||!visit?.id)throw new Error('حُفظ المكان لكن تعذر العثور على الزيارة الأولى؛ حاول تحديث البيانات');const quickName=formValue('quickItemName');if(quickName){const rawQuickPrice=formValue('quickItemPrice'),quickPrice=rawQuickPrice===''?null:Number(rawQuickPrice);if(quickPrice!==null&&(!Number.isFinite(quickPrice)||quickPrice<0))throw new Error('سعر الصنف يجب أن يكون رقمًا موجبًا أو يُترك فارغًا');const {error:ie}=await sup.from('items').insert({place_id:placeId,visit_id:visit.id,owner_id:state.me.id,name:quickName,price:quickPrice,rating:4.5});if(ie)alertToast('تم حفظ المكان، لكن تعذر حفظ الصنف؛ يمكنك إضافته يدويًا')}}
 localStorage.removeItem(STORAGE_DRAFT);closeModal();await loadData({silent:true});render();openModal('detail',placeId);alertToast(old?'تم تعديل المكان':'تم حفظ تجربتك الأولى ✨')})}
async function saveItem(form){await safeSave(form,async()=>{const place=state.places.find(p=>p.id===form.dataset.place),visit=state.visits.find(v=>v.id===form.dataset.visit),id=form.dataset.id,old=state.items.find(x=>x.id===id);if(!place||!visit||!own(place))throw new Error('لا توجد صلاحية');const name=formValue('itemName'),priceRaw=formValue('itemPrice'),price=priceRaw===''?null:Number(priceRaw),rt=num($('#ratingValue').value),notes=formValue('itemNotes');if(!name||rt<0.5||rt>5||Math.abs(rt*2-Math.round(rt*2))>1e-8)throw new Error('اسم الصنف والتقييم مطلوبان');if(price!==null&&(!Number.isFinite(price)||price<0))throw new Error('السعر اختياري، وإن أدخلته يجب أن يكون رقمًا صفر أو أكثر');const image=await chosenPhoto('itemPhoto','items'),payload={name,price,rating:rt,notes,...image?{photo_url:image.url,photo_credit:image.credit,photo_source:image.source}:{}};let result;if(old)result=await sup.from('items').update(payload).eq('id',id);else result=await sup.from('items').insert({...payload,place_id:place.id,visit_id:visit.id,owner_id:state.me.id});if(result.error)throw result.error;await loadData({silent:true});render();openModal('detail',place.id);alertToast('تم حفظ الصنف وتقييمه ⭐')})}
async function saveReceipt(form){await safeSave(form,async()=>{const id=form.dataset.id,visit=state.visits.find(v=>v.id===id),place=state.places.find(p=>p.id===visit?.place_id);if(!visit||!own(place))throw new Error('لا توجد صلاحية');const photo=await uploadPhoto('receiptPhoto','receipts'),total=formValue('receiptTotal'),{error}=await sup.from('visits').update({total_override:total===''?null:num(total),tax_enabled:$('#receiptTax').checked,tax_rate:5,...photo?{receipt_url:photo}:{}}).eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('detail',place.id);alertToast('تم حفظ فاتورة الزيارة')})}
async function saveProfile(form){await safeSave(form,async()=>{const display_name=formValue('profileName'),username=formValue('profileUsername').toLowerCase(),bio=formValue('profileBio');if(!display_name||!/^[a-z0-9]{4,24}$/.test(username))throw new Error('اسم المستخدم يجب أن يتكون من 4 إلى 24 حرفًا أو رقمًا إنجليزيًا دون رموز أو مسافات');const photo=await uploadPhoto('profilePhoto','avatars'),{error}=await sup.from('profiles').update({display_name,username,bio,...photo?{avatar_url:photo}:{}}).eq('id',state.me.id);if(error)throw error;await loadData({silent:true});closeModal();render();alertToast('تم تحديث حسابك')})}
async function adminCreateUser(form){await safeSave(form,async()=>{if(!admin())throw Error('لا توجد صلاحية');
 const username=formValue('newUsername').toLowerCase(),display_name=formValue('newDisplay'),password=$('#newPassword')?.value||'';
 if(!/^[a-z0-9]{4,24}$/.test(username)||display_name.length<1||password.length<8)throw Error('تأكد من صحة اسم المستخدم والاسم وكلمة المرور');
 await spotAccountAction('admin_create',{username,display_name,password},true);
 await loadData({silent:true});openModal('admin');alertToast('تم إنشاء حساب بدون بريد إلكتروني')})}
async function openItemEditor(placeId,visitId){
 let visit=state.visits.find(v=>v.id===visitId&&v.place_id===placeId);
 if(!visit){
  try{const {data,error}=await sup.from('visits').select('*').eq('id',visitId).eq('place_id',placeId).maybeSingle();if(error)throw error;if(data){state.visits=state.visits.filter(v=>v.id!==data.id).concat(data);visit=data}}catch(e){console.warn('Could not retrieve selected visit',e)}
 }
 if(!visit)return alertToast('تعذر فتح هذه الزيارة، يرجى تحديث البيانات والمحاولة مرة أخرى');
 const p=state.places.find(x=>x.id===placeId);
 if(!p||!own(p))return alertToast('لا توجد صلاحية لإضافة صنف هنا');
 openModal('item',placeId,{visitId:visit.id});
 if(!$('#itemForm'))alertToast('تعذر فتح نموذج الصنف، حاول مرة أخرى');
}
async function addVisit(placeId){if(!requiredLogin())return;const p=state.places.find(x=>x.id===placeId);if(!p||!own(p))return;const go=confirm(`إضافة زيارة جديدة اليوم إلى ${p.name}؟\nكل زيارة لها أصناف وفاتورة خاصة.`);if(!go)return;try{const {error}=await sup.from('visits').insert({place_id:placeId,owner_id:state.me.id,visited_at:new Date().toISOString()});if(error)throw error;await loadData({silent:true});render();openModal('detail',placeId);alertToast('أضفنا زيارة جديدة، تقدر تضيف أصنافها الآن')}catch(e){alertToast('تعذر إضافة الزيارة: '+e.message)}}
async function deleteVisit(id){const v=state.visits.find(x=>x.id===id),p=state.places.find(x=>x.id===v?.place_id);if(!v||!own(p)||!confirm('حذف هذه الزيارة وجميع أصنافها؟ لا يمكن التراجع.'))return;try{let r=await sup.from('items').delete().eq('visit_id',id);if(r.error)throw r.error;r=await sup.from('visits').delete().eq('id',id);if(r.error)throw r.error;await loadData({silent:true});render();openModal('detail',p.id);alertToast('تم حذف الزيارة')}catch(e){alertToast('تعذر الحذف: '+e.message)}}
async function deleteItem(id){const it=state.items.find(x=>x.id===id),p=state.places.find(x=>x.id===it?.place_id);if(!it||!own(p)||!confirm('حذف هذا الصنف وتقييمه نهائيًا؟'))return;try{const {error}=await sup.from('items').delete().eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('detail',p.id);alertToast('تم حذف الصنف')}catch(e){alertToast('تعذر حذف الصنف: '+e.message)}}
async function toggleUser(id){if(!admin()||id===state.me.id)return;const u=state.people.find(x=>x.id===id);if(!u||!confirm(`${u.is_active?'إيقاف':'تفعيل'} حساب ${u.display_name}؟`))return;try{const {error}=await sup.from('profiles').update({is_active:!u.is_active}).eq('id',id);if(error)throw error;await loadData({silent:true});render();openModal('admin');alertToast('تم تحديث صلاحية المستخدم')}catch(e){alertToast('تعذر تغيير حالة الحساب: '+e.message)}}
async function deletePlace(id){const p=state.places.find(x=>x.id===id);if(!p||!own(p)||!confirm(`حذف «${p.name}» وجميع زياراته وأصنافه نهائيًا؟ لا يمكن التراجع.`))return;try{let r=await sup.from('items').delete().eq('place_id',id);if(r.error)throw r.error;r=await sup.from('visits').delete().eq('place_id',id);if(r.error)throw r.error;r=await sup.from('places').delete().eq('id',id);if(r.error)throw r.error;closeModal();await loadData({silent:true});render();alertToast('تم حذف المكان')}catch(e){alertToast('تعذر الحذف: '+e.message)}}
async function copyShare(p){const u=shareUrl(p);try{await navigator.clipboard.writeText(u);alertToast('تم نسخ رابط المشاركة الحقيقي')}catch{window.prompt('انسخ رابط المشاركة الحقيقي:',u)}}
async function ownerShareApp(useShare){
 if(!admin()){alertToast('هذه الخاصية متاحة لمدير المنصة فقط');return}
 const url=SPOT_PUBLIC_APP_URL;
 if(useShare&&navigator.share){
  try{await navigator.share({title:'Spot — Every Place Has a Story',text:'Spot: discover and share your favorite cafés and restaurants.',url});return}
  catch(e){if(e?.name==='AbortError')return}
 }
 try{await navigator.clipboard.writeText(url);alertToast('تم نسخ رابط Spot الرسمي')}catch{window.prompt('انسخ رابط Spot الرسمي:',url)}
}
async function shareMe(){const p=state.me;if(!p)return;const url=shareUrl(p);try{if(navigator.share)await navigator.share({title:`ذوق ${p.display_name} — Spot`,text:'تجربتي للأماكن على Spot',url});else await copyShare(p)}catch(e){if(e.name!=='AbortError')await copyShare(p)}}
async function saveSlug(){if(!state.me)return;const slug=formValue('publicSlug').toLowerCase();if(!/^[a-z0-9_-]{4,40}$/.test(slug))return alertToast('الرابط 4–40 حرفًا من الإنجليزي والأرقام - أو _');try{const {error}=await sup.from('profiles').update({public_slug:slug}).eq('id',state.me.id);if(error)throw error;await loadData({silent:true});closeModal();render();alertToast('تم تحديث رابط المشاركة، والرابط القديم لم يعد صالحًا')}catch(e){alertToast('لم يُحفظ الرابط، قد يكون مستخدمًا بالفعل')}}
function backup(){if(!state.me)return requiredLogin();const id=state.me.id,p=state.me.role==='admin',ids=new Set(state.places.filter(x=>p||x.owner_id===id).map(x=>x.id)),payload={app:'SPOT',version:APP_VERSION,exported_at:new Date().toISOString(),note:'الصور محفوظة كرابط URL. هذا الملف ليس نسخة مستقلة من الصور أو كلمات المرور.',profiles:p?state.people:[state.me],places:state.places.filter(x=>ids.has(x.id)),visits:state.visits.filter(x=>ids.has(x.place_id)),items:state.items.filter(x=>ids.has(x.place_id)),saved_places:[...state.likes]};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`thawaq-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000);alertToast('نسختك الاحتياطية جاهزة للتحميل')}
async function refresh(){if(!READY)return alertToast('اتصال Supabase غير جاهز');try{await loadData({silent:true});render();alertToast('تم تحديث بياناتك ✓ بدون تحديث إصدار التطبيق')}catch(e){alertToast('تعذرت المزامنة: '+e.message)}}
async function logout(){if(!confirm('هل أنت متأكد من تسجيل الخروج؟'))return;await spotUnregisterPush();await sup?.auth.signOut();spotCloseStory(false);state.stories=[];state.storySeen.clear();state.followRequests=[];state.places=[];state.visits=[];state.items=[];state.posts=[];state.discoverPosts=[];state.session=null;state.me=null;spotHardStopCamera();spotResetStoryCache();state.tab='home';state.likes=new Set();closeModal();render();alertToast('تم تسجيل الخروج')}
function collectPreview(input){if(input.id==='placePhoto'){window.SPOT_PLACE_CROP?.load(input);return}const id=input.id+'Preview',img=$('#'+id);if(!img)return;const f=input.files?.[0];if(!f){img.classList.add('hidden');return}img.src=URL.createObjectURL(f);img.classList.remove('hidden')}
function updateResults(){if(state.tab!=='discover')return;const grid=$('#filteredGrid'),counter=$('#resultsCount');if(!grid)return;const mode=state.discoverMode;if(mode==='opinions'){queueDiscoverSearch();return;}if(mode==='people'){const people=discoverMembers();grid.innerHTML=people.map(memberCard).join('')||'<div class="notice">لا يوجد أشخاص بهذا البحث.</div>';if(counter)counter.textContent=`${people.length} عضو في نتائج البحث`;return;}const rows=getFilters(state.places);grid.innerHTML=rows.map(placeTile).join('')||'<div class="notice">ما لقينا أماكن بهذا البحث.</div>';if(counter)counter.textContent=`${rows.length} مكان في نتائج البحث`;}
function navigate(id,{socialView='following'}={}){closeModal();if(id==='community'){state.socialView=socialView;if(socialView==='following')state.socialQuery=''}state.tab=id;state.publicMode=false;history.replaceState({},'',location.pathname);render()}
async function handleAction(el){const act=el.dataset.action,id=el.dataset.id;if(await spotStoryAction(act,id,el))return;switch(act){case 'close-modal':closeModal();break;case 'open-web-images':openWebLibrary(id);break;case 'close-web-images':clearWebLibrary();break;case 'pick-google-from-album':chooseGooglePhotoFromAlbum();break;case 'discover-more':state.discoverPage++;await searchDiscoverPosts(false);break;case 'new-place':openModal('place');break;case 'login':openModal('login');break;case 'signup':openModal('signup');break;case 'forgot-password':openModal('forgot');break;case 'redeem-password':openModal('redeem');break;case 'reset-status':await spotResetStatus();break;case 'reset-requests':await spotOwnerResetRequests();break;case 'spot-reset-approve':await spotOwnerResolveReset(id,true);break;case 'spot-reset-reject':await spotOwnerResolveReset(id,false);break;case 'spot-reset-copy':await navigator.clipboard.writeText(el.dataset.code||'');alertToast('تم نسخ رمز الاستعادة');break;case 'go-discover':navigate('discover');break;case 'diary-favs':navigate('diary');state.diaryFilter='favorites';render();break;case 'favorite':await toggleFavorite(id);break;case 'new-item':requestAnimationFrame(()=>openItemEditor(id,el.dataset.visit));break;case 'back-to-place':openModal('detail',id);break;case 'edit-item':{const item=state.items.find(x=>x.id===id);if(item)openModal('item',item.place_id,{visitId:item.visit_id,itemId:id});break}case 'edit-place':openModal('place',id);break;case 'receipt':openModal('receipt',id);break;case 'add-visit':await addVisit(id);break;case 'delete-visit':await deleteVisit(id);break;case 'delete-item':await deleteItem(id);break;case 'toggle-user':await toggleUser(id);break;case 'delete-place':await deletePlace(id);break;case 'maps':{const p=state.places.find(x=>x.id===id);if(p?.maps_url&&validGoogleMapLink(p.maps_url))window.open(p.maps_url,'_blank','noopener,noreferrer');else alertToast('لا يوجد رابط Google Maps مسجل لهذا المكان');break}case 'edit-place-map':{openModal('place',id);$('#placeMapsUrl')?.focus();break}case 'share-me':await shareMe();break;case 'copy-me':if(state.me)await copyShare(state.me);break;case 'copy-spot-app':await ownerShareApp(false);break;case 'share-spot-app':await ownerShareApp(true);break;case 'settings':openModal('settings');break;case 'edit-profile':openModal('profile');break;case 'save-slug':await saveSlug();break;case 'admin-users':await reportClientVersion(true);await loadClientVersions();openModal('admin');break;case 'admin-new-user':openModal('admin-new');break;case 'mark-candidate-tested':await markCandidateTested();break;case 'approve-release-all':await approveCandidateForAll();break;case 'refresh':await refresh();break;case 'backup':backup();break;case 'enable-notifications':await enableNotifications();break;case 'check-app-update':await checkAppUpdate();break;case 'social-feed':navigate('community');break;
case 'social-members':navigate('community',{socialView:'members'});break;
case 'social-alerts':navigate('community',{socialView:'alerts'});break;
case 'go-insights':navigate('insights');break;case 'open-inbox':state.dmTarget=null;navigate('messages');break;case 'open-chat':await spotOpenChat(id);break;
case 'show-member':openModal('member',id);break;
case 'toggle-follow':await toggleFollow(id);break;case 'toggle-post-like':await spotTogglePostLike(id);break;
case 'toggle-member-alert':await toggleMemberAlerts(id);break;
case 'open-notice':await openNotice(id);break;
case 'read-all-social':await markAllRead();break;
case 'open-post':{const post=state.posts.find(p=>p.id===id);if(post)openModal('detail',post.place_id);break;}
case 'logout':await logout();break;case 'exit-share':state.shareSlug=null;state.publicMode=false;navigate('home');break}}
async function handleSubmit(form){if(form.id==='spotStoryForm')return spotSaveStory(form);if(form.id==='loginForm')return login(form);if(form.id==='spotResetRequestForm')return requestSpotReset(form);if(form.id==='spotResetRedeemForm')return redeemSpotReset(form);if(form.id==='signupForm')return signup(form);if(form.id==='placeForm')return savePlace(form);if(form.id==='itemForm')return saveItem(form);if(form.id==='receiptForm')return saveReceipt(form);if(form.id==='profileForm')return saveProfile(form);if(form.id==='adminNewForm')return adminCreateUser(form);if(form.id==='spotDmForm')return spotSendMessage(form)}
function wire(){initRatingDrag();const bar=$('.header-tools');if(bar&&!$('#spotFindPeopleBtn')){const button=document.createElement('button');button.type='button';button.id='spotFindPeopleBtn';button.className='icon-button spot-find-people';button.setAttribute('aria-label',spotUi('البحث عن مستخدمين','Search members'));button.setAttribute('title',spotUi('بحث الأعضاء','Find members'));button.innerHTML=ico('search',19);bar.insertBefore(button,document.getElementById('refreshBtn'));button.addEventListener('click',()=>{navigate('community',{socialView:'members'});setTimeout(()=>$('#memberSearch')?.focus(),40)})}document.getElementById('spotInboxBtn')?.addEventListener('click',()=>{state.dmTarget=null;navigate('messages')});document.addEventListener('click',async e=>{const cho=e.target.closest('[data-choice]');if(cho){$('#placeType').value=cho.dataset.choice;$$('[data-choice]').forEach(b=>b.classList.toggle('active',b===cho));return}const nav=e.target.closest('[data-tab]');if(nav){navigate(nav.dataset.tab);return}const action=e.target.closest('[data-action]');if(action){e.preventDefault();e.stopImmediatePropagation();await handleAction(action);return}const item=e.target.closest('[data-place]:not(form)');if(item)openModal('detail',item.dataset.place)});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#spotStoryViewer')&&!$('#spotStoryComposer')){$('#imageLibraryOverlay')?clearWebLibrary():closeModal();}if(e.key==='Enter'&&e.target.id==='webPhotoQuery'){e.preventDefault();$('#googleImageSearchLink')?.click();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-place]')){e.preventDefault();openModal('detail',e.target.dataset.place)}});
 document.addEventListener('submit',e=>{if(e.target.matches('form')){e.preventDefault();handleSubmit(e.target)}});
 document.addEventListener('change',e=>{if(e.target.matches('input[type=file]')){if(e.target.id==='placePhoto'||e.target.id==='itemPhoto'){delete state.webPhotoByInput[e.target.id];const hint=$('#'+e.target.id+'Source');if(hint)hint.textContent='صورة من الألبوم أو الكاميرا';}collectPreview(e.target);}if(e.target.id==='cityFilter'||e.target.id==='sortFilter'){state.filter[e.target.id==='cityFilter'?'city':'sort']=e.target.value;updateResults()}});
 document.addEventListener('input',e=>{if(e.target.id==='webPhotoQuery'){updateGoogleImageLink();return;}if(e.target.id==='spotDmSearch'){state.dmSearch=e.target.value;const box=$('#spotDmPeerList');if(box){const people=state.people.filter(p=>p.is_active!==false&&p.id!==state.me?.id&&(p.username+' '+p.display_name).toLowerCase().includes(state.dmSearch.trim().toLowerCase()));box.innerHTML=people.map(p=>`<button class="spot-dm-peer" data-action="open-chat" data-id="${escape(p.id)}">${avatar(p)}<span><b>${escape(p.display_name)}</b><small>@${escape(p.username)}</small></span></button>`).join('')||'<p class="muted-small">لا يوجد مستخدم بهذا الاسم.</p>'}return;}if(e.target.id==='memberSearch'){state.socialQuery=e.target.value;const matches=state.people.filter(p=>p.id!==state.me?.id&&p.is_active!==false).filter(p=>(p.username+' '+p.display_name).toLowerCase().includes(state.socialQuery.toLowerCase().replace(/^@/,'').trim()));if(state.socialView!=='members'){state.socialView='members';render();const inp=$('#memberSearch');if(inp){inp.focus();inp.setSelectionRange(inp.value.length,inp.value.length)}}else{const out=$('#memberResults');if(out)out.innerHTML=matches.map(memberCard).join('')||'<div class="notice">ما لقينا أعضاء بهذا الاسم.</div>'}return;}if(e.target.id==='searchPlaces'){state.filter.q=e.target.value;updateResults()}if(e.target.closest('#placeForm')&&e.target.type!=='file'){const form=$('#placeForm');if(!form.dataset.id){localStorage.setItem(STORAGE_DRAFT,JSON.stringify({name:formValue('placeName'),city:formValue('placeCity'),type:formValue('placeType'),notes:formValue('placeNotes'),quickItem:formValue('quickItemName'),quickPrice:formValue('quickItemPrice')}))}}});
 document.addEventListener('click',e=>{const disc=e.target.closest('[data-discover-tab]');if(disc){state.discoverMode=disc.dataset.discoverTab;render();return;}const chip=e.target.closest('[data-type]');if(chip){state.filter.type=chip.dataset.type;$$('[data-type]').forEach(b=>b.classList.toggle('active',b===chip));updateResults()}const soc=e.target.closest('[data-social-tab]');if(soc){state.socialView=soc.dataset.socialTab;state.socialQuery='';render();return;}const dc=e.target.closest('[data-diary]');if(dc){state.diaryFilter=dc.dataset.diary;render()}});
 $('#refreshBtn').addEventListener('click',refresh);$('#avatarBtn').addEventListener('click',()=>navigate('account'));window.addEventListener('online',()=>{state.online=true;refresh()});window.addEventListener('offline',()=>{state.online=false;render()});window.addEventListener('popstate',()=>{state.shareSlug=new URLSearchParams(location.search).get('share')||window.__THAWAQ_SHARE_SLUG__||null;state.publicMode=!!state.shareSlug;render()});
}
function configureStandaloneTouch(){
 const standalone=window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;
 if(!standalone)return;
 document.documentElement.classList.add('thawaq-standalone');
 const viewport=document.querySelector('meta[name="viewport"]');
 if(viewport)viewport.setAttribute('content','width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover');
 const preventGesture=e=>{if(e.cancelable)e.preventDefault()};
 document.addEventListener('gesturestart',preventGesture,{passive:false});
 document.addEventListener('gesturechange',preventGesture,{passive:false});
 document.addEventListener('touchmove',e=>{if(e.touches?.length>1&&e.cancelable)e.preventDefault()},{passive:false});
}
function startClock(){const tick=()=>{const stamp=new Date();const clock=stamp.toLocaleString(window.SPOT_I18N?.language==='en'?'en-AE':'ar-AE',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});$('#liveTime').textContent=clock;$('#headerDateRow').textContent=clock};tick();setInterval(tick,1000)}
function connectRealtime(){if(!sup)return;state.channels.forEach(c=>sup.removeChannel(c));state.channels=[];const ch=sup.channel('thawaq-v3-app-data').on('postgres_changes',{event:'*',schema:'public',table:'places'},onData).on('postgres_changes',{event:'*',schema:'public',table:'items'},onData).on('postgres_changes',{event:'*',schema:'public',table:'visits'},onData).on('postgres_changes',{event:'*',schema:'public',table:'profiles'},onData).on('postgres_changes',{event:'*',schema:'public',table:'app_release'},onData).on('postgres_changes',{event:'*',schema:'public',table:'social_posts'},onData).on('postgres_changes',{event:'*',schema:'public',table:'social_follows'},onData).on('postgres_changes',{event:'*',schema:'public',table:'spot_follow_requests'},onData).on('postgres_changes',{event:'*',schema:'public',table:'spot_stories'},onData).on('postgres_changes',{event:'*',schema:'public',table:'spot_story_views'},onData).on('postgres_changes',{event:'INSERT',schema:'public',table:'social_notifications'},onSocialNotice).on('postgres_changes',{event:'INSERT',schema:'public',table:'spot_activity_notifications'},onSocialNotice).on('postgres_changes',{event:'*',schema:'public',table:'spot_post_likes'},async payload=>{const id=payload.new?.post_id||payload.old?.post_id;if(id)try{await spotLoadLikeStats([id])}catch{}}).on('postgres_changes',{event:'INSERT',schema:'public',table:'spot_direct_messages'},async payload=>{if(!state.me||![payload.new.sender_id,payload.new.recipient_id].includes(state.me.id))return;await spotLoadMessages();if(state.tab==='messages'){const draft=$('#spotDmText')?.value||'';render();const input=$('#spotDmText');if(input)input.value=draft;await spotMarkMessagesRead()}else{alertToast('💬 رسالة جديدة من مجتمع Spot')}}).subscribe();state.channels.push(ch)}
async function onSocialNotice(payload){if(payload?.new?.recipient_id!==state.me?.id)return;const before=unread();await loadSocial();if(unread()>before)alertToast('🔔 '+(payload.new.kind==='follow_request'?'عندك طلب متابعة جديد':payload.new.kind==='follow_accepted'?'تم قبول طلب متابعتك':payload.new.kind==='like'?'أحد الأعضاء أعجب بمنشورك':payload.new.kind==='follow'?'عندك متابع جديد':'عندك تجربة جديدة من شخص تتابعه'));if(!$('#modalLayer').classList.contains('show'))render()}
let nextSync=null;function onData(){clearTimeout(nextSync);nextSync=setTimeout(async()=>{try{await loadData({silent:true});if(!$('#modalLayer').classList.contains('show'))render();else state.needsRefresh=true}catch{}},1300)}

async function ensureAppWorker(){
 if(!('serviceWorker' in navigator)||PREVIEW_ONLY)return null;
 try{return await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'})}
 catch(e){console.warn('PWA registration issue',e);return null}
}
function pushKeyBytes(base64){const pad='='.repeat((4-base64.length%4)%4);const raw=atob((base64+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function enableNotifications(){
 if(!requiredLogin())return;
 if(PREVIEW_ONLY)return alertToast('إشعارات النسخة التجريبية غير مفعلة');
 if(!('serviceWorker' in navigator)||!('PushManager' in window)||typeof Notification==='undefined')return alertToast('الإشعارات الخارجية غير مدعومة هنا. في الآيفون ثبّت Spot على الشاشة الرئيسية أولًا.');
 if(!window.matchMedia('(display-mode: standalone)').matches && !navigator.standalone && /iPhone|iPad|iPod/.test(navigator.userAgent)) return alertToast('على الآيفون: ثبّت Spot عبر مشاركة ← إضافة إلى الشاشة الرئيسية، ثم فعّل الإشعارات منه.');
 const key=window.APP_CONFIG?.PUSH_PUBLIC_KEY;
 if(!key)return alertToast('مفتاح الإشعارات غير مهيّأ');
 try{
  const permission=await Notification.requestPermission();
  if(permission!=='granted')return alertToast('لتلقي الإشعارات الخارجية اسمح بإشعارات Spot من إعدادات الجهاز.');
  const reg=(await ensureAppWorker())||await navigator.serviceWorker.ready;
  let subscription=await reg.pushManager.getSubscription();
  if(!subscription)subscription=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:pushKeyBytes(key)});
  const {data:{session}}=await sup.auth.getSession();
  if(!session)throw Error('يجب تسجيل الدخول أولًا');
  const res=await fetch(`${SURL}/functions/v1/push-notifications`,{method:'POST',headers:{'Content-Type':'application/json',apikey:SKEY,authorization:`Bearer ${session.access_token}`},body:JSON.stringify({action:'register',subscription:subscription.toJSON(),userAgent:navigator.userAgent})});
  if(!res.ok)throw Error('تعذر تسجيل الجهاز للإشعارات');
  alertToast('تم تفعيل إشعارات Spot لهذا الجهاز 🔔');
 }catch(e){console.error(e);alertToast('تعذر تفعيل الإشعارات: '+(e.message||'تحقق من إذن الإشعارات'))}
}
async function checkAppUpdate(){
 if(!('serviceWorker' in navigator))return alertToast('تحديث التطبيق غير مدعوم في هذا المتصفح');
 try{
  const reg=(await ensureAppWorker())||await navigator.serviceWorker.ready;
  await reg.update();
  if(!reg.waiting)return alertToast('لا يوجد تحديث تطبيق جاهز للتثبيت. لم تُحدّث إلا حالة الفحص.');
  if(state.me&&confirm('تحديث جديد جاهز. هل تريد أخذ نسخة احتياطية أولًا؟'))backup();
  if(!confirm('هل تريد تثبيت التحديث الآن؟ يمكن اختيار «إلغاء» للاستمرار بالإصدار الحالي.'))return;
  reg.waiting.postMessage({type:'SKIP_WAITING'});
  await new Promise(resolve=>{let done=false;const finish=()=>{if(!done){done=true;resolve()}};navigator.serviceWorker.addEventListener('controllerchange',finish,{once:true});setTimeout(finish,5000)});
  location.reload();
 }catch(e){console.error(e);alertToast('تعذر فحص تحديث التطبيق، حاول مرة أخرى.')}
}

async function init(){configureStandaloneTouch();wire();startClock();if(!PREVIEW_ONLY)ensureAppWorker();state.publicMode=!!state.shareSlug;try{if(!sup)throw new Error('لم تكتمل تهيئة الاتصال؛ تأكد من إعدادات Spot.');const {data:{session}}=await sup.auth.getSession();state.session=session;await loadData({silent:true});connectRealtime();const openPostId=new URLSearchParams(location.search).get('post');if(new URLSearchParams(location.search).get('messages')&&state.me){state.tab='messages';const who=new URLSearchParams(location.search).get('user');if(who&&state.people.some(p=>p.id===who&&p.is_active!==false))state.dmTarget=who;}const newFollowId=new URLSearchParams(location.search).get('user');if(newFollowId&&!new URLSearchParams(location.search).has('messages')&&state.me&&state.people.some(p=>p.id===newFollowId))setTimeout(()=>openModal('member',newFollowId),400);if(openPostId){const post=state.posts.find(p=>p.id===openPostId);if(post){state.socialView='following';state.tab='community';setTimeout(()=>openModal('detail',post.place_id),250)}}sup.auth.onAuthStateChange((ev,newSession)=>{const oldId=state.session?.user?.id,newId=newSession?.user?.id;state.session=newSession;if(oldId!==newId){spotCloseStory(false);state.places=[];state.visits=[];state.items=[];state.posts=[];state.stories=[];state.discoverPosts=[];state.followRequests=[];state.storySeen.clear();spotPushSyncedFor='';Promise.resolve().then(()=>loadData({silent:true})).then(render).catch(console.error)}})}catch(e){console.error(e);state.online=false;alertToast('تعذر تحميل بيانات Spot؛ تحقق من الاتصال')}
 render();const draft=localStorage.getItem(STORAGE_DRAFT);if(draft&&state.me){$('#previewTop')?.setAttribute('title','يمكن استعادة مسودة التجربة عند فتح صفحة الإضافة');}
}
// Spot daily stories and account privacy. All content access is also enforced by RLS.
let spotPushSyncedFor='';
function spotCanView(id){const p=state.people.find(x=>x.id===id);return !!p&&p.is_active!==false&&(!p.is_private||id===state.me?.id||!!myFollow(id))}
function spotPrivateProfile(p){return `<div class="spot-private-card card card-pad">${avatar(p,'avatar-large')}<h2>${escape(p.display_name||p.username)}</h2><p>@${escape(p.username)}</p><span class="pill">🔒 حساب خاص</span><p>المنشورات والستوريات متاحة للمتابعين المقبولين فقط.</p>${state.me?followControls(p):btn('سجّل الدخول لإرسال طلب متابعة','login','primary')}</div>`}
function followControls(p){if(!state.me||p.id===state.me.id)return '';const edge=myFollow(p.id),pending=state.followRequests.some(x=>x.requester_id===state.me.id&&x.recipient_id===p.id);return `<div class="follow-controls">${p.is_private?'<span class="pill">🔒 خاص</span>':''}${btn(edge?'✓ أتابعه':pending?'تم إرسال الطلب · إلغاء':p.is_private?'طلب متابعة':'+ متابعة','toggle-follow',edge?'soft sm':'primary sm',`data-id="${escape(p.id)}"`)}${edge?btn(edge.notify_new_posts?'🔔 التنبيهات مفعّلة':'🔕 تنبيهات العضو','toggle-member-alert',edge.notify_new_posts?'soft sm':'outline sm',`data-id="${escape(p.id)}"`):''}</div>`}
function spotRequestList(){const rows=state.followRequests.filter(x=>x.recipient_id===state.me?.id);return rows.length?`<section class="spot-request-list"><h3>طلبات المتابعة <span class="pill">${rows.length}</span></h3>${rows.map(r=>{const p=state.people.find(x=>x.id===r.requester_id);return `<div class="spot-request-row">${avatar(p)}<span><b>${escape(p?.display_name||'عضو Spot')}</b><small>@${escape(p?.username||'')}</small></span>${btn('قبول','accept-follow','primary sm',`data-id="${escape(r.requester_id)}"`)}${btn('رفض','reject-follow','outline sm',`data-id="${escape(r.requester_id)}"`)}</div>`}).join('')}</section>`:''}
function spotPrivacySettings(){return `<div class="subsection spot-privacy-settings"><h3>خصوصية الحساب</h3><p>حسابك ${state.me?.is_private?'خاص؛ المتابعون المقبولون فقط يشاهدون منشوراتك وستورياتك.':'عام؛ يمكن للجميع مشاهدة منشوراتك.'} المتابعون الحاليون يبقون عند التحويل إلى خاص.</p>${btn(state.me?.is_private?'🔒 حساب خاص · تحويل إلى عام':'🌐 حساب عام · تحويل إلى خاص','toggle-privacy','outline wide')}${state.me?.is_private?btn('إعادة تأمين الصور المرفوعة','retry-privacy','outline wide'):''}${spotRequestList()}<small class="muted-small">صورة الحساب والاسم يبقيان ظاهرين للبحث عنك.</small></div>`}
function spotOpenPrivacy(){if(!requiredLogin())return;showModal('الخصوصية وطلبات المتابعة',spotPrivacySettings()+(!state.followRequests.some(x=>x.recipient_id===state.me.id)?'<p class="notice">لا توجد طلبات متابعة معلّقة.</p>':''))}
async function toggleFollow(id){if(!requiredLogin())return;try{const {data,error}=await sup.rpc('spot_request_follow',{target:id});if(error)throw error;await loadData({silent:true});if($('#modalLayer').classList.contains('show'))openModal('member',id);else render();alertToast(data==='requested'?'تم إرسال طلب المتابعة':data==='cancelled'?'تم إلغاء الطلب':data==='unfollowed'?'تم إلغاء المتابعة':'تمت المتابعة')}catch(e){alertToast('تعذر تغيير المتابعة: '+e.message)}}
async function spotResolveFollow(id,accept){try{const {error}=await sup.rpc('spot_resolve_follow',{requester:id,accept_request:accept});if(error)throw error;await loadData({silent:true});render();spotOpenPrivacy();alertToast(accept?'تم قبول طلب المتابعة':'تم رفض الطلب')}catch(e){alertToast('تعذر معالجة الطلب: '+e.message)}}
async function spotChangePrivacy(button,desired){if(!requiredLogin())return;const next=typeof desired==='boolean'?desired:!state.me.is_private;if(next!==state.me.is_private&&!confirm(next?'تحويل الحساب إلى خاص؟ تبقى متابعاتك الحالية، والمتابعات الجديدة تحتاج قبولك.':'تحويل الحساب إلى عام؟ ستصبح منشوراتك وستورياتك متاحة للجميع.'))return;button.disabled=true;button.textContent='جاري حفظ الخصوصية وتأمين الصور…';try{const {data:{session}}=await sup.auth.getSession();const r=await fetch(`${SURL}/functions/v1/spot-privacy`,{method:'POST',headers:{apikey:SKEY,authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({is_private:next})});const body=await r.json();if(!r.ok||!body.ok)throw Error('لم يكتمل تأمين الصور. اختر «إعادة تأمين الصور المرفوعة» لإكمال العملية.');await loadData({silent:true});render();spotOpenPrivacy();alertToast(next?'حسابك خاص الآن':'حسابك عام الآن')}catch(e){await loadData({silent:true}).catch(()=>{});spotOpenPrivacy();alertToast(e.message)}finally{button.disabled=false}}
function spotHomeWelcome(){const first=state.me?.display_name?.split(' ')[0];return `<section class="spot-home-welcome"><div><span class="eyebrow">YOUR DAILY SPOT</span><h1>${first?'حيّاك، '+escape(first):'كل مكان له حكاية'}<span class="spot-welcome-spark">✦</span></h1><p>لحظة اليوم، وتجربة تستاهل تنحفظ.</p></div><div class="spot-home-actions">${btn(ico('plus')+' تجربة جديدة','new-place','primary')}${btn('🔔'+(unread()?` ${unread()}`:''),'social-alerts','outline','aria-label="التنبيهات وطلبات المتابعة"')}</div></section>`}
function storyTray(){if(!state.me)return `<section class="spot-story-section card card-pad"><b>لحظات اليوم على Spot</b><p class="muted-small">سجّل دخولك وشارك صورة أو فيديو يختفي بعد 24 ساعة.</p>${btn('سجّل الدخول','login','outline sm')}</section>`;const ids=followingIds(),groups=new Map();for(const s of state.stories.filter(x=>Date.parse(x.expires_at)>Date.now()&&spotCanView(x.owner_id)&&(x.owner_id===state.me.id||ids.has(x.owner_id)))){if(!groups.has(s.owner_id))groups.set(s.owner_id,[]);groups.get(s.owner_id).push(s)}const ordered=[...groups.entries()].sort((a,b)=>{if(a[0]===state.me.id)return -1;if(b[0]===state.me.id)return 1;return Number(b[1].some(x=>!state.storySeen.has(x.id)))-Number(a[1].some(x=>!state.storySeen.has(x.id)))||Date.parse(b[1].at(-1).created_at)-Date.parse(a[1].at(-1).created_at)});return `<section class="spot-story-section card"><div class="spot-story-heading"><div><span class="eyebrow">DAILY STORIES</span><h2>لحظات اليوم</h2></div><small>تختفي بعد 24 ساعة</small></div><div class="spot-story-tray" id="spotStoryTray"><button class="spot-story-chip spot-story-add" data-action="new-story" aria-label="إضافة ستوري"><span class="spot-story-ring">${avatar(state.me)}<b>+</b></span><span>أضف لحظة</span></button>${ordered.map(([id,rows])=>{const p=state.people.find(x=>x.id===id),unseen=rows.some(x=>!state.storySeen.has(x.id));return `<button class="spot-story-chip ${unseen?'is-unseen':'is-seen'}" data-action="open-stories" data-id="${escape(id)}" aria-label="ستوريات ${escape(p?.display_name)}، ${unseen?'غير مشاهدة':'تمت المشاهدة'}"><span class="spot-story-ring">${avatar(p)}</span><span>${id===state.me.id?'قصتك':escape(p?.display_name?.split(' ')[0]||p?.username)}</span></button>`}).join('')}${!groups.size?`<span class="spot-story-empty">${state.storyError?'تعذر تحميل الستوريات. اضغط تحديث البيانات.':'شارك لحظة من يومك<br>وقرّب ذوقك من أصحابك.'}</span>`:''}</div></section>`}
async function spotResolveMedia(){const records=[...state.places,...state.visits,...state.items],keys=['cover_url','photo_url','receipt_url'];const paths=[...new Set(records.flatMap(r=>keys.map(k=>r['_'+k]||r[k]).filter(v=>typeof v==='string'&&v.startsWith('spot-media:')).map(v=>v.slice(11))))];if(!paths.length)return;const {data,error}=await sup.storage.from('spot-private').createSignedUrls(paths,90);const urls=new Map((data||[]).filter(x=>x.signedUrl).map(x=>[x.path,x.signedUrl]));for(const r of records)for(const key of keys){const stored=r['_'+key]||r[key];if(stored?.startsWith('spot-media:')){const old=r[key];r['_'+key]=stored;r[key]=error?'':urls.get(stored.slice(11))||'';for(const el of $$('img[src],a[href]')){if(el.getAttribute('src')===old)el.setAttribute('src',r[key]);if(el.getAttribute('href')===old)el.setAttribute('href',r[key])}}}}
setInterval(()=>{if(state.online&&!document.hidden)spotResolveMedia().catch(()=>{})},60000);
async function spotPushRequest(action,extra={}){const {data:{session}}=await sup.auth.getSession();if(!session)throw Error('سجّل الدخول أولًا');const r=await fetch(`${SURL}/functions/v1/push-notifications`,{method:'POST',headers:{apikey:SKEY,authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,...extra})});const data=await r.json().catch(()=>({}));if(!r.ok||data.ok===false)throw Error(data.error==='NO_SUBSCRIPTION'?'فعّل الإشعارات على هذا الجهاز أولًا':'تعذر الاتصال بخدمة الإشعارات');return data}
async function spotSyncPush(){if(PREVIEW_ONLY||!state.me||typeof Notification==='undefined'||Notification.permission!=='granted'||!('serviceWorker' in navigator)||spotPushSyncedFor===state.me.id)return;try{const reg=await ensureAppWorker(),subscription=await reg?.pushManager?.getSubscription();if(subscription){await spotPushRequest('register',{subscription:subscription.toJSON(),userAgent:navigator.userAgent});spotPushSyncedFor=state.me.id}}catch(e){console.warn('Push registration refresh failed',e)}}
async function spotUnregisterPush(){spotPushSyncedFor='';if(PREVIEW_ONLY||!('serviceWorker' in navigator))return;try{const reg=await navigator.serviceWorker.getRegistration(),sub=await reg?.pushManager?.getSubscription();if(sub){try{await spotPushRequest('unregister',{endpoint:sub.endpoint})}finally{await sub.unsubscribe()}}}catch(e){console.warn('Could not remove device subscription',e)}}
