async function legacySpotStoryAction(act,id,el){switch(act){case 'new-story':spotNewStory();return true;case 'open-stories':await spotOpenStories(id);return true;case 'close-story':spotCloseStory();return true;case 'next-story':await spotMoveStory(1);return true;case 'previous-story':await spotMoveStory(-1);return true;case 'pause-story':if(spotStorySession){spotStorySession.paused=!spotStorySession.paused;const video=$('#spotStoryViewer video');if(video){if(spotStorySession.paused)video.pause();else video.play().catch(()=>{})}el.textContent=spotStorySession.paused?'▶':'Ⅱ';el.setAttribute('aria-label',spotStorySession.paused?'تشغيل':'إيقاف مؤقت')}return true;case 'delete-story':{const s=spotStorySession?.rows[spotStorySession.index];if(!s||s.owner_id!==state.me?.id||!confirm('حذف هذه الستوري؟'))return true;const {error}=await sup.from('spot_stories').delete().eq('id',s.id).eq('owner_id',state.me.id);if(error){alertToast('تعذر حذف الستوري');return true}await sup.storage.from('spot-stories').remove([s.media_path]);spotCloseStory(false);await spotLoadStories();render();alertToast('تم حذف الستوري');return true}case 'privacy-settings':spotOpenPrivacy();return true;case 'toggle-privacy':await spotChangePrivacy(el);return true;case 'retry-privacy':await spotChangePrivacy(el,true);return true;case 'accept-follow':await spotResolveFollow(id,true);return true;case 'reject-follow':await spotResolveFollow(id,false);return true;case 'test-notifications':await spotTestPush(el);return true;default:return false}}
