function spotStoryTime(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return d.toLocaleTimeString(window.SPOT_I18N?.language==='en'?'en-AE':'ar-AE',{hour:'numeric',minute:'2-digit',hour12:true})}
function spotStoryRelative(value){const mins=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));return mins<1?'الآن':mins<60?`منذ ${mins} د`:`منذ ${Math.floor(mins/60)} س`}
function spotSourceLabel(source){return source==='album'?'مرفوعة من ألبوم الصور':source==='camera'?'التُقطت بكاميرا Spot':''}
function spotProfileAvatar(p){const rows=state.stories.filter(s=>s.owner_id===p.id&&Date.parse(s.expires_at)>Date.now()&&spotCanView(p.id)),unseen=rows.some(s=>!state.storySeen.has(s.id)),mine=p.id===state.me?.id;const inner=avatar(p,'spot-profile-avatar');return rows.length?`<button type="button" class="spot-profile-story ${unseen?'is-unseen':'is-seen'}" data-action="open-stories" data-id="${escape(p.id)}" aria-label="ستوريات ${escape(p.display_name)}، ${unseen?'غير مشاهدة':'تمت المشاهدة'}">${inner}<span class="spot-profile-story-label">${mine?'قصتك':'شاهد الستوري'}</span></button>`:mine?`<button type="button" class="spot-profile-story is-empty" data-action="new-story" aria-label="إضافة ستوري من حسابي">${inner}<i>+</i><span class="spot-profile-story-label">أضف لحظة</span></button>`:`<div class="spot-profile-story">${inner}</div>`}
function spotStudioIcon(name){const icons={close:'<path d="m6 6 12 12M6 18 18 6"/>',flip:'<path d="M20 7H4l4-4M4 17h16l-4 4M4 7v5m16 5v-5"/>',album:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 3-3 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',pause:'<path d="M8 5v14m8-14v14"/>',play:'<path d="m8 5 11 7-11 7Z"/>',sound:'<path d="M11 4 6 8H3v8h3l5 4ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="M11 4 6 8H3v8h3l5 4Zm5 5 6 6m-6 0 6-6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="m9 5 7 7-7 7"/>',fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 8h8v8H8Z"/>',retry:'<path d="M20 10a8 8 0 1 0-2 8M20 3v7h-7"/>'};return `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.close}</svg>`}
function spotStopStream(stream){stream?.getTracks().forEach(t=>t.stop())}

function spotCloseComposer(force=false){const run=spotComposer;if(!run)return true;if(run.saving&&!force){alertToast('انتظر اكتمال رفع الستوري');return false}spotComposer=null;run.composition?.observer.disconnect();clearInterval(run.recordTimer);clearTimeout(run.recordLimit);if(run.recorder?.state==='recording'){run.discardRecording=true;try{run.recorder.stop()}catch{}}spotReleaseCamera(run);if(run.previewURL)URL.revokeObjectURL(run.previewURL);$('#spotStoryComposer')?.remove();document.body.classList.remove('spot-story-open');return true}
