document.addEventListener('change',e=>{if(e.target.id==='spotStoryAlbum'){const file=e.target.files?.[0];if(file)spotSelectStoryFile(file,'album');e.target.value=''}if(e.target.id==='spotStoryNativeCamera'){const file=e.target.files?.[0];if(file)spotSelectStoryFile(file,'camera');e.target.value=''}});
document.addEventListener('keydown',e=>{const overlay=$('#spotStoryComposer')||$('#spotStoryViewer');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();if(spotComposer)spotCloseComposer();else if($('#spotStorySheet'))spotCloseStorySheet();else spotCloseStory()}if(spotStorySession&&!$('#spotStorySheet')){if(e.key==='PageDown'){e.preventDefault();spotMoveOwner(1)}if(e.key==='PageUp'){e.preventDefault();spotMoveOwner(-1)}if(e.key==='ArrowRight')spotMoveStory(1);if(e.key==='ArrowLeft')spotMoveStory(-1);if(e.code==='Space'&&!e.target.matches('button,input,textarea')){e.preventDefault();spotSetPause('user',!spotStorySession.reasons.has('user'))}}if(e.key==='Tab'){const scope=$('#spotStorySheet')||overlay,controls=$$('button:not([disabled]),input:not(.spot-native-input),textarea',scope).filter(x=>x.getClientRects().length),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
